/// Sorts a slice using the merge sort algorithm, returning a new sorted `Vec`.
///
/// # Complexity
///
/// - **Time:** O(n log n) in all cases (best, average, worst).
/// - **Space:** O(n) auxiliary space for the temporary buffers used during merging.
///
/// # Arguments
///
/// * `v` - A slice of elements that implement `Ord` and `Clone`.
///
/// # Returns
///
/// A new `Vec<T>` containing the sorted elements.
///
/// # Examples
///
/// ```
/// use merge_sort::merge_sort;
///
/// let v = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let sorted = merge_sort(&v);
/// assert_eq!(sorted, vec![1, 1, 2, 3, 4, 5, 6, 9]);
/// ```
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

