// Pool is a fixed-size worker pool that executes submitted functions concurrently.
type Pool struct {
	n        int
	tasks    chan func() error
	results  chan error
	wg       sync.WaitGroup
	mu       sync.Mutex
	shutdown bool
	panics   []any
}

// New creates a new Pool with n workers.
func New(n int) *Pool {
	if n <= 0 {
		n = 1
	}
	p := &Pool{
		n:       n,
		tasks:   make(chan func() error),
		results: make(chan error, n),
	}
	for i := 0; i < n; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for task := range p.tasks {
		p.execute(task)
	}
}

// execute runs a single task, recovering from panics.
func (p *Pool) execute(task func() error) {
	var err error
	func() {
		defer func() {
			if r := recover(); r != nil {
				p.mu.Lock()
				p.panics = append(p.panics, r)
				p.mu.Unlock()
				err = fmt.Errorf("panic: %v", r)
			}
		}()
		err = task()
	}()
	p.results <- err
}

